INSERT OR REPLACE INTO programs (id, data, date, updated_at) VALUES ('ex-p1', '{"title": "사랑의 연탄 나눔", "category": "전사", "date": "2026-11-07", "deadline": "2026-11-02", "time": "09:00–13:00", "place": "서울 노원구 중계본동", "meeting": "중계본동 주민센터 앞", "bring": "편한 운동화, 여벌 옷 (토시·앞치마는 현장 지급)", "desc": "홀몸 어르신 12가구에 겨울 연탄 1,200장을 손에서 손으로 전달해요. 체력 부담이 적은 구간도 있으니 처음 오시는 분도 환영해요.", "capacity": 30, "cover": "d6e2afaa5186ef6e607dfdfde22b5e55", "status": "open", "sample": true, "applyMode": "site", "questions": []}', '2026-11-07', 0);
INSERT OR REPLACE INTO programs (id, data, date, updated_at) VALUES ('ex-p2', '{"title": "한강 지천 줍깅 (플로깅)", "category": "연구소", "date": "2026-11-14", "deadline": "2026-11-11", "time": "10:00–12:00", "place": "중랑천 산책로", "meeting": "군자교 아래 운동기구 쉼터", "bring": "텀블러 (집게·봉투 제공)", "desc": "4km 구간을 걸으며 쓰레기를 줍고, 종류별로 분류해 무게를 기록해요. 가족 동반도 가능해요.", "capacity": 20, "cover": "77d3a0d79178620164b8f4bf9489deb4", "status": "open", "sample": true, "applyMode": "site", "questions": []}', '2026-11-14', 0);
INSERT OR REPLACE INTO programs (id, data, date, updated_at) VALUES ('ex-p3', '{"title": "지역아동센터 수학·영어 학습 멘토링", "category": "본사", "date": "2026-11-21", "deadline": "2026-11-15", "time": "14:00–17:00", "place": "성동구 지역아동센터", "bring": "없음", "desc": "초등 고학년 아이들과 1:2로 숙제를 함께 봐요. 정기 참여(월 1회)가 가능한 분이면 더 좋아요.", "capacity": 8, "cover": "7c3c87b1f871c62a885998fe7c6be585", "status": "open", "sample": true, "applyMode": "site", "questions": []}', '2026-11-21', 0);
INSERT OR REPLACE INTO programs (id, data, date, updated_at) VALUES ('ex-p4', '{"title": "김장 나눔 한마당", "category": "공장", "date": "2026-12-05", "deadline": "2026-11-28", "time": "08:30–14:00", "place": "사옥 앞 광장", "bring": "고무장갑 (앞치마 제공)", "desc": "배추 600포기를 함께 버무려 저소득 가정 150곳에 전달해요.", "capacity": 40, "cover": "bf5251f04deb1c3db6d4793207a727b7", "status": "open", "sample": true, "applyMode": "site", "questions": []}', '2026-12-05', 0);
INSERT OR REPLACE INTO archive (id, data, date, updated_at) VALUES ('ex-a1', '{"title": "해변 정화 활동", "category": "연구소", "date": "2026-09-19", "place": "인천 을왕리 해변", "participants": 26, "summary": "해변 1.2km 구간에서 쓰레기 410kg을 수거했어요. 가장 많이 나온 건 스티로폼 부표 조각과 페트병이었어요.", "photos": ["132948c9f0e21ee8162da7315e5eda22", "e457d797b31d856abc6eebe7e8a04ee9", "b36477109f1162b6c0038076f5cefbce", "f746cb83d42d50e161fa216642682dd3", "fc4504431ddc480052624d9e58e47761"], "sample": true}', '2026-09-19', 0);
INSERT OR REPLACE INTO archive (id, data, date, updated_at) VALUES ('ex-a2', '{"title": "임직원 단체 헌혈", "category": "본사", "date": "2026-07-10", "place": "사옥 1층 로비", "participants": 64, "summary": "헌혈 버스 2대가 하루 동안 머물렀고, 모인 헌혈증 52장은 소아암 환아 가족에게 기부했어요.", "photos": ["90cc9ca6de225c1ed1e9bbd7a57e7c6a", "9e6c4bb4f5e60dc6c4f0719c5ec51c9b", "7afc81d859cc7033d965bc3df4b2d338"], "sample": true}', '2026-07-10', 0);
